CREATE INDEX IF NOT EXISTS idx_company_spend_limits_company
    ON public.company_spend_limits (company_id);

-- UNIQUE (company_id, period, scope) NÃO cobre o caso scope IS NULL (NULL != NULL no Postgres).
-- Garantimos no máximo UM teto "da empresa inteira" (scope NULL) por período com índice parcial.
CREATE UNIQUE INDEX IF NOT EXISTS idx_company_spend_limits_one_default
    ON public.company_spend_limits (company_id, period) WHERE scope IS NULL;
